using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNAccess {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_FullFloor/";static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";static Vector3 origin=new Vector3(0,-34,0);static JObject Plan()=>JObject.Parse(File.ReadAllText(H+"layout.json"));
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");return s;}
 static List<Vector3> Points(JToken t)=>t["path"].Select(p=>origin+new Vector3((float)p[0],0,-(float)p[1])).ToList();
 public static object Corridors(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;bool enabled=cc.enabled;var result=new List<object>();var samples=new List<object>();try{cc.enabled=false;Physics.SyncTransforms();foreach(var t in Plan()["tunnels"]){var ps=Points(t);int tested=0;var issues=new List<object>();for(int i=1;i<ps.Count;i++){var dir=(ps[i]-ps[i-1]).normalized;var right=Vector3.Cross(Vector3.up,dir);float len=Vector3.Distance(ps[i-1],ps[i]);for(float d=0;d<=len;d+=.30f){var p=ps[i-1]+dir*d;foreach(float side in new[]{-1.25f,0,1.25f}){var q=p+right*side;tested++;var hit=Physics.OverlapCapsule(q+Vector3.up*.42f,q+Vector3.up*1.45f,.32f,~0,QueryTriggerInteraction.Ignore);bool floor=Physics.Raycast(q+Vector3.up*.2f,Vector3.down,out var f,.4f,~0,QueryTriggerInteraction.Ignore);if(hit.Length>0||!floor){if(issues.Count<12)issues.Add(new{p=new[]{q.x,q.y,q.z},side,floor,blocks=hit.Select(c=>c.name).Distinct().ToArray()});}}}}samples.Add(new{id=(string)t["id"],tested,passed=issues.Count==0,issues});cc.enabled=false;player.transform.position=ps[0]+Vector3.up*(cc.height*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();float remaining=0;int steps=0;bool pass=true;foreach(var target in ps.Skip(1)){int max=(int)(Vector3.Distance(player.transform.position,target)/.08f)+100;for(int i=0;i<max;i++){var d=target-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.03f)break;cc.Move(d.normalized*Mathf.Min(.08f,remaining)+Vector3.down*.045f);steps++;}if(remaining>.08f){pass=false;break;}}float feet=player.transform.position.y+cc.center.y-cc.height*.5f;pass&=Mathf.Abs(feet+34)<.15f;result.Add(new{id=(string)t["id"],passed=pass,remaining,steps,feet,position=new[]{player.transform.position.x,player.transform.position.y,player.transform.position.z}});cc.enabled=false;}}
 finally{cc.enabled=false;player.transform.position=old;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}var o=new{controller=result,clearance=samples};File.WriteAllText(O+"corridors.json",JsonConvert.SerializeObject(o,Formatting.Indented));return o;}
 public static object Access(){var s=Check();var plan=Plan();var additions=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_DomeNetwork/layout.json"));foreach(var p in additions["placements"])((JArray)plan["placements"]).Add(p.DeepClone());var cc=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player")).GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;Physics.SyncTransforms();var rows=new List<object>();try{foreach(var r in plan["rooms"]){string id=(string)r["id"];float rad=(float)r["r"];var center=origin+new Vector3((float)r["x"],0,-(float)r["v"]);float cell=.32f;int n=Mathf.CeilToInt(rad/cell);var free=new HashSet<Vector2Int>();for(int x=-n;x<=n;x++)for(int z=-n;z<=n;z++){if(x*x+z*z>n*n)continue;var p=center+new Vector3(x*cell,0,z*cell);if(!Physics.Raycast(p+Vector3.up*.25f,Vector3.down,out var f,.4f,~0,QueryTriggerInteraction.Ignore)||Mathf.Abs(f.point.y+34)>.08f)continue;if(Physics.OverlapCapsule(p+Vector3.up*.42f,p+Vector3.up*1.45f,.32f,~0,QueryTriggerInteraction.Ignore).Length==0)free.Add(new Vector2Int(x,z));}if(free.Count==0)throw new Exception("No floor "+id);Vector2Int closest(Vector3 p)=>free.OrderBy(q=>Vector2.Distance(new Vector2(q.x*cell,q.y*cell),new Vector2(p.x,p.z))).First();var start=closest(new Vector3(0,0,id=="C01"?3:0));var seen=new HashSet<Vector2Int>{start};var queue=new Queue<Vector2Int>();queue.Enqueue(start);while(queue.Count>0){var p=queue.Dequeue();foreach(var d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var q=p+d;if(free.Contains(q)&&seen.Add(q))queue.Enqueue(q);}}var targets=new List<object>();foreach(var d in r["doors"]){var v=new Vector3((float)d["x"],0,(float)d["z"]);var q=closest(v);float error=Vector2.Distance(new Vector2(q.x*cell,q.y*cell),new Vector2(v.x,v.z));targets.Add(new{id=(string)d["id"],reachable=seen.Contains(q)&&error<.65f,error});}foreach(var p in plan["placements"].Where(p=>(string)p["room"]==id)){float yaw=(float)p["yaw"];var rot=Quaternion.Euler(0,yaw,0);var pos=new Vector3((float)p["position"][0],0,(float)p["position"][2]);var cen=new Vector3((float)p["center"][0],0,(float)p["center"][2]);var goal=pos+rot*(cen+Vector3.forward*((float)p["size"][2]*.5f+.6f));var q=closest(goal);float error=Vector2.Distance(new Vector2(q.x*cell,q.y*cell),new Vector2(goal.x,goal.z));targets.Add(new{id=(string)p["name"],reachable=seen.Contains(q)&&error<.70f,error});}rows.Add(new{id,free=free.Count,connected=seen.Count,targets});}}
 finally{cc.enabled=enabled;Physics.SyncTransforms();}File.WriteAllText(O+"access.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return rows;}
 static void Shot(string n,Vector3 pos,Vector3 target,float fov=76){var g=new GameObject("BM_TemporaryCamera");g.hideFlags=HideFlags.HideAndDontSave;var c=g.AddComponent<Camera>();c.transform.position=origin+pos;c.transform.LookAt(origin+target);c.nearClipPlane=.04f;c.farClipPlane=400;c.fieldOfView=fov;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Capture(){var s=Check();var p=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=p.activeSelf;p.SetActive(false);try{var plan=Plan();var t=plan["tunnels"].First(t=>(string)t["id"]=="B2-T01");var ps=Points(t).Select(v=>v-origin).ToList();int k=Math.Min(5,ps.Count-2);var pos=ps.Count>2?ps[k]:Vector3.Lerp(ps[0],ps.Last(),.22f);Shot("01_pipe_tunnel",pos+Vector3.up*1.65f,ps.Last()+Vector3.up*1.60f);Shot("02_centrifuge",new Vector3(-24,1.65f,-5.5f),new Vector3(-17,1.6f,0));Shot("03_cooling_connected",new Vector3(19,1.65f,-9),new Vector3(19,3.2f,2));foreach(string id in new[]{"W02","E01","E02","N01","C04"}){var r=plan["rooms"].First(r=>(string)r["id"]==id);var center=new Vector3((float)r["x"],0,-(float)r["v"]);float rad=(float)r["r"];Shot("room_"+id,center+new Vector3(-rad*.35f,1.65f,-rad*.60f),center+new Vector3(0,1.6f,rad*.2f));}Shot("04_freight_junction",new Vector3(44,1.65f,30),new Vector3(39,1.65f,28));}finally{p.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{images=9};}
 public static object Show(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork");Selection.activeGameObject=root.transform.Find("B2_PipeCorridors/B2_T01_VL_C02").gameObject;var temp=new GameObject("BM_EditorView");var ps=Points(Plan()["tunnels"].First(t=>(string)t["id"]=="B2-T01"));temp.transform.position=ps[Math.Min(5,ps.Count-2)]+Vector3.up*1.65f;temp.transform.LookAt(ps.Last()+Vector3.up*1.6f);if(SceneView.lastActiveSceneView)SceneView.lastActiveSceneView.orthographic=false;SceneView.lastActiveSceneView?.AlignViewToObject(temp.transform);UnityEngine.Object.DestroyImmediate(temp);return new{shown="T01 pipe corridor"};}
}
